5: /// <summary>
6: /// TEST-MCP-PATHNORM-001 (criterion unitgreen-native-host) / TR-MCP-PATHNORM-001 (plan P1.4c): the
7: /// native boundary decides by the injected host, so both its Windows-host and its non-Windows-host
8: /// behavior are proven on every test host against a simulated host, without a host-conditional skip
9: /// (TR-MCP-USECASE-018 AC-006: no unit test depends on the platform). BDP v4: MockData then Real.
10: /// </summary>
11: public abstract class WorkspaceNativePathHostContractTests
12: {
13:     /// <summary>The host-aware native-spelling function under test.</summary>
14:     protected abstract string ToNativePath(string path, WorkspacePathPlatform platform, IWorkspaceHostEnvironment host);
15: 
16:     /// <summary>On a Windows host, Windows-platform paths switch to backslashes.</summary>
17:     [Theory]
18:     [InlineData("C:/Users/kingd/repo", @"C:\Users\kingd\repo")]
19:     [InlineData("C:/", @"C:\")]
20:     [InlineData("//srv/share/x", @"\\srv\share\x")]
21:     [InlineData(@"C:\already\native", @"C:\already\native")]
22:     public void WindowsHost_WindowsPath_UsesBackslashes(string path, string expected)
23:     {
24:         AssertNative(expected, ToNativePath(path, WorkspacePathPlatform.Windows, SimulatedWorkspaceHosts.Windows()));
25:     }
26: 
27:     /// <summary>On a non-Windows host nothing is rewritten, whatever the platform tag.</summary>
28:     [Theory]
29:     [InlineData("C:/Users/kingd/repo", WorkspacePathPlatform.Windows)]
30:     [InlineData("//srv/share/x", WorkspacePathPlatform.Windows)]
31:     [InlineData("/home/x/repo", WorkspacePathPlatform.CaseSensitive)]
32:     public void NonWindowsHost_IsUnchanged(string path, WorkspacePathPlatform platform)
33:     {
34:         AssertUnchanged(path, ToNativePath(path, platform, SimulatedWorkspaceHosts.Linux()));
35:     }
36: 
37:     /// <summary>Assertion shared by the non-Windows-host contract and its negative controls.</summary>
38:     /// <param name="path">Path given to the native-spelling function.</param>
39:     /// <param name="actual">Value the function returned.</param>
40:     protected static void AssertUnchanged(string path, string actual) => Assert.Equal(path, actual);
41: 
42:     /// <summary>Assertion shared by the Windows-host contract and its negative controls.</summary>
43:     /// <param name="expected">Backslash spelling the requirement defines.</param>
44:     /// <param name="actual">Value the function returned.</param>
45:     protected static void AssertNative(string expected, string actual) => Assert.Equal(expected, actual);
46: }
