48: /// <summary>BDP v4 step 2: the host-aware native-boundary contract against a literal data table.</summary>
49: public sealed class WorkspaceNativePathHostMockDataTests : WorkspaceNativePathHostContractTests
50: {
51:     private static readonly Dictionary<(string, WorkspacePathPlatform), string> WindowsHost = new()
52:     {
53:         [("C:/Users/kingd/repo", WorkspacePathPlatform.Windows)] = @"C:\Users\kingd\repo",
54:         [("C:/", WorkspacePathPlatform.Windows)] = @"C:\",
55:         [("//srv/share/x", WorkspacePathPlatform.Windows)] = @"\\srv\share\x",
56:         [(@"C:\already\native", WorkspacePathPlatform.Windows)] = @"C:\already\native",
57:         [("/home/x/repo", WorkspacePathPlatform.CaseSensitive)] = "/home/x/repo",
58:     };
59: 
60:     /// <inheritdoc />
61:     protected override string ToNativePath(string path, WorkspacePathPlatform platform, IWorkspaceHostEnvironment host)
62:     {
63:         ArgumentNullException.ThrowIfNull(host);
64:         if (host.Platform != WorkspacePathPlatform.Windows)
65:             return path;
66: 
67:         return WindowsHost.TryGetValue((path, platform), out var native)
68:             ? native
69:             : throw new InvalidOperationException($"No scripted native spelling for '{path}' ({platform}).");
